// Copies the onnxruntime-web runtime files the flyer tool's "Enhance (AI)"
// step loads at runtime into public/ort/, so the site serves them itself (no
// outside CDN). They are build output (~45 MB, git-ignored), regenerated by
// the predev / prebuild hooks in package.json.
import { copyFileSync, existsSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const from = join(root, "node_modules", "onnxruntime-web", "dist");
const to = join(root, "public", "ort");

const files = [
  // WebGPU build (fast path) and the WebAssembly CPU build (fallback).
  "ort.webgpu.min.mjs",
  "ort-wasm-simd-threaded.asyncify.mjs",
  "ort-wasm-simd-threaded.asyncify.wasm",
  "ort.wasm.min.mjs",
  "ort-wasm-simd-threaded.mjs",
  "ort-wasm-simd-threaded.wasm",
];

mkdirSync(to, { recursive: true });
for (const file of files) {
  const source = join(from, file);
  if (!existsSync(source)) {
    console.error(`copy-ort-runtime: missing ${source} (is onnxruntime-web installed?)`);
    process.exit(1);
  }
  copyFileSync(source, join(to, file));
}
console.log(`copy-ort-runtime: copied ${files.length} files to public/ort`);
